// Pattern 1: 2-D REALSXP matrix (rpart.c:241, 261, 269)
//   allocMatrix(REALSXP, nrow, ncol) produces SEXPREC with:
//     s->type   = REALSXP (14)
//     s->length = nrow * ncol
//     s->nrow   = nrow    (column j starts at REAL(s) + j * nrow)
//     s->ncol   = ncol
//     s->data   = double[nrow * ncol], zero-initialized via memset
//   REAL(s) returns (double *) s->data; pointer arithmetic dptr += nrow
//   advances one full column (column-major layout).
//
// Pattern 2: 2-D INTSXP matrix (rpart.c:278, 285, 293)
//   allocMatrix(INTSXP, nrow, ncol) produces SEXPREC with:
//     s->type   = INTSXP (13)
//     s->length = nrow * ncol
//     s->nrow   = nrow    (column j starts at INTEGER(s) + j * nrow)
//     s->ncol   = ncol
//     s->data   = int[nrow * ncol], zero-initialized via memset
//   INTEGER(s) returns (int *) s->data.  The zero-fill loop in rpart.c:299-300
//   is redundant with the memset but compiles and runs correctly.
//
// Both patterns share the same inline Rf_allocMatrix function (from INTSXP.h):
//
//   inline SEXP allocMatrix(SEXPTYPE type, int nrow, int ncol) {
//       SEXP s = allocVector(type, nrow * ncol);
//       s->nrow = nrow;
//       s->ncol = ncol;
//       return s;
//   }
//   inline SEXP Rf_allocMatrix(SEXPTYPE type, int nrow, int ncol) {
//       return allocMatrix(type, nrow, ncol);
//   }
//
// Invariant 1 (C++ exception-based errors): allocVector throws RError (a
// std::runtime_error subclass) on malloc failure.  If the SEXPREC node
// allocation fails, RError is thrown immediately.  If the data buffer
// allocation fails, the node is freed before RError is thrown.  No
// partial SEXP objects remain after a throw.
//
// Invariant 2 (arena-backed memory without source modification): The SEXPREC
// node and data buffer are heap-allocated via malloc() inside allocVector,
